  isolation: { drive: 'G:', runner: 'run.mjs', output: basename(run), home: 'h', profile: 'h/profiles/qa',
    temp: 'tmp', pnpmStore: 'pnpm-store', wslTmpdir: linux(temp) } };
let host, server, stdout = '', stderr = '';

class ProbeInputError extends Error {
  constructor(field) {
    super('invalid recipe input');
    this.field = field;
  }
}

async function evaluateProbe(source, probe) {
  const allowed = new Set(['recipe', 'stdin', 'args', 'files']);
  if (!probe || Object.keys(probe).some(key => !allowed.has(key)) ||
      !['engineering-python-syntax', 'engineering-json'].includes(probe.recipe)) throw Error('invalid probe scope');
  // Report only the field name. The receipt must never echo an argv path or stdin.
  if (probe.files !== undefined && (!Array.isArray(probe.files) || probe.files.length !== 0)) throw new ProbeInputError('files');
  let target = null;
  if (probe.recipe === 'engineering-python-syntax') {
    if (!Array.isArray(probe.args) || probe.args.length !== 1 || !files.includes(probe.args[0]) ||
        !Object.hasOwn(source.bytes, probe.args[0])) throw new ProbeInputError('args');
    if (probe.stdin !== undefined) throw new ProbeInputError('stdin');
    [target] = probe.args;
  } else {
    if (probe.args !== undefined && (!Array.isArray(probe.args) || probe.args.length !== 0)) throw new ProbeInputError('args');
    if (probe.stdin !== undefined && (typeof probe.stdin !== 'string' || Buffer.byteLength(probe.stdin) > 8192)) {
      throw new ProbeInputError('stdin');
    }
  }
  // Pass data over stdin so no payload or path reaches an operating-system command interpreter.
  const args = ['-d', 'Ubuntu', '--exec', '/usr/bin/env', 'TMPDIR=' + linux(temp), 'PYTHONDONTWRITEBYTECODE=1',
    '/usr/bin/python3', '-B', linux(join(here, 'review-probe.py')), linux(source.location), linux(join(here, 'python_syntax.py'))];
  const child = spawn('wsl.exe', args, { ...context, stdio: ['pipe', 'pipe', 'ignore'] });
  const output = [];
  let size = 0;
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => { child.kill(); reject(Error('review probe timed out')); }, 12_000);
    child.stdin.on('error', reject);
    child.on('error', reject);
    child.stdout.on('data', data => {
      size += data.length;
      if (size > 16384) { child.kill(); reject(Error('review probe output too large')); }
      else output.push(data);
    });
    child.on('close', code => {
      clearTimeout(timeout);
      if (code !== 0) { reject(Error('review probe runner unavailable')); return; }
      try { resolve(JSON.parse(Buffer.concat(output))); } catch (error) { reject(error); }
    });
    child.stdin.end(JSON.stringify({ target, ...(probe.stdin !== undefined ? { stdin: probe.stdin } : {}) }));
  });
}

function createDiagnostics(caseInventory) {
  const observed = new Map();
  const preparedProbes = new Set();
  return createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/engineering-check' || req.headers.authorization !== 'Bearer ' + diagKey) {
      res.writeHead(404).end();
      return;
    }
    try {
      const chunks = [];
      let length = 0;
      for await (const chunk of req) {
        length += chunk.length;
        if (length > 2_097_152) throw Error('diagnostics payload cap');
        chunks.push(chunk);
      }
      const q = JSON.parse(Buffer.concat(chunks));
      const stage = q.checkSet === 'engineering-g1' ? 'g1' : q.checkSet === 'engineering-g2' ? 'g2' : undefined;
      const envelope = { spec: 'building-loop/diagnostics/2', requestId: q.requestId, snapshotSha256: q.snapshotSha256 };
      if (!stage || q.spec !== envelope.spec || !['check', 'probe'].includes(q.operation) || !Array.isArray(q.artifacts) ||
          JSON.stringify(q.artifacts.map(item => item.path)) !== JSON.stringify(files) || typeof q.requestId !== 'string' ||
          !/^[a-f0-9]{64}$/u.test(q.snapshotSha256)) throw Error('unexpected diagnostics contract');
      for (const ids of [q.protectedCases, q.requiredCases]) {
        if (!Array.isArray(ids) || ids.some(id => !caseInventory[stage].includes(id))) throw Error('unregistered case');
      }
      const source = Object.fromEntries(q.artifacts.filter(item => item.sha256 !== null).map(item => {
        const bytes = Buffer.from(item.contentBase64, 'base64');
        if (digest(bytes) !== item.sha256) throw Error('diagnostics artifact integrity');
        return [item.path, bytes];
      }));
