from __future__ import annotations

import argparse
from concurrent.futures import ThreadPoolExecutor
from hashlib import sha256
import json
from pathlib import Path
import re
import subprocess
from time import perf_counter

from base_assess import execute, json_equal, request, row

ROOT = Path(__file__).resolve().parent

def retention_small():
    item = request([row("anchor"), row("bridge", deps=["anchor"]), row("tip", deps=["bridge"]), row("remove", 3)],
                   action="rollback", budget=0, applied=["anchor", "tip", "remove"], retain=["tip"])
    item.pop("action")
    return item, {"actions":["remove"], "units":3}

def retention_branched(layers=26):
    # A modest-width directed acyclic graph with many paths through the same
    # unapplied nodes. Traversal should see each intermediate once.
    changes = [row("anchor"), row("remove", 3)]
    previous = ["anchor"]
    for index in range(layers):
        current = [f"layer-{index}-{suffix}" for suffix in ("left", "right")]
        changes.extend(row(name, deps=previous) for name in current)
        previous = current
    changes.append(row("tip", deps=previous))
    item = request(changes, action="rollback", budget=0, applied=["anchor", "tip", "remove"], retain=["tip"])
    item.pop("action")
    return item, {"actions":["remove"], "units":3}

def mixed_ordering():
    first = request([row("p")], action="rollback", environment="production", applied=["p"])
    first.pop("action")
    return [first, None], {"status":"error","error":"production-frozen","requestIndex":0,"results":[],"units":0}

def equivalent_key_order():
    first = request([row("retry", 2)], action="rollback", budget=0, applied=["retry"], retain=[])
    first.pop("action")
    first["operation_id"] = "op-0"
    second = dict(reversed(list(first.items())))
    return [first, second], {"status":"ok","results":[{"actions":["retry"],"units":2,"operationId":"op-0"}],"units":2}

def payload(case, g4):
    name, generator = case
    data, expected = generator()
    if isinstance(data, list):
        requests = data
    else:
        requests = [data]
    if g4:
        requests = [{**item, "operation_id":f"op-{i}"} if isinstance(item, dict) and "operation_id" not in item
                    else item for i, item in enumerate(requests)]
    envelope = {"action":"rollback-many", "requests":requests}
    if g4:
        envelope["limit"] = 10
    if name.startswith("retention"):
        if g4:
            expected["operationId"] = "op-0"
        expected = {"status":"ok","results":[expected],"units":expected["units"]}
    return envelope, expected

def test(source, stage, case):
    incoming, expected = payload(case, stage == "g2")
    started = perf_counter()
    try:
        actual, code, error = execute(source, incoming)
        status = "passed" if code == 0 and json_equal(actual, expected) else "failed"
    except subprocess.TimeoutExpired:
        actual, code, error, status = None, None, "wall timeout at evaluator 3s", "timeout"
    return {"case":case[0], "input":incoming, "expected":expected, "actual":actual,
            "status":status, "exitCode":code, "error":error, "elapsedMs":round((perf_counter() - started) * 1000, 1)}

def pins(source):
    return [{"path":name,"sha256":sha256((source / name).read_bytes()).hexdigest() if (source / name).is_file() else None}
            for name in ("journal.py","planner.py","policy.py","release.py")]

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("runs", nargs="+")
    args = parser.parse_args()
    assert all(re.fullmatch(r"r-[A-Za-z0-9]+", run) for run in args.runs)
    cases = (("retention-small",retention_small),("retention-shared-unapplied-dag",retention_branched),
             ("error-order-early-domain-vs-later-invalid-item",mixed_ordering))
    tasks, missing = [], []
    for run in args.runs:
        for mode in ("standard","standard-checklist","building-loop"):
            for stage in ("g1","g2"):
                record_path = ROOT / run / f"{mode}-{stage}.json"
                if not record_path.is_file():
                    missing.append({"run":run,"mode":mode,"stage":stage})
                    continue
                recorded = json.loads(record_path.read_bytes())
                source = ROOT / run / "frozen" / mode / stage
                assert pins(source) == recorded["after"]
                tasks.append((run,mode,stage,source))
    rows = []
    with ThreadPoolExecutor(max_workers=3) as pool:
        for run, mode, stage, source in tasks:
            stage_cases = cases + (("object-key-order-does-not-charge-twice", equivalent_key_order),) if stage == "g2" else cases
            checks = list(pool.map(lambda case: test(source, stage, case), stage_cases))
            rows.append({"run":run,"mode":mode,"stage":"G3" if stage=="g1" else "G4",
                         "artifactPins":pins(source),"cases":checks})
    path = ROOT / "hard-targeted-public.json"
    path.write_text(json.dumps({"spec":"building-loop-hard-public-performance-recheck/1",
        "scope":"Additional public-spec stress and ordering cases outside online and postfreeze scores.",
        "frozenStagesMissing":missing,"results":rows}, ensure_ascii=False, indent=2)+"\n",
        encoding="utf-8", newline="\n")
    for row in rows:
        print(row["run"],row["mode"],row["stage"],[(case["case"],case["status"],case["elapsedMs"]) for case in row["cases"]])

if __name__ == "__main__":
    main()

