    if not retained <= applied:
        raise JournalError("invalid-retain")
    return retained


# G3: the batch rollback envelope. Only these two top-level keys exist; every
# other key is a malformed envelope rather than an ignored extra.
BATCH_KEYS = frozenset({"action", "requests"})

# G3: per-item parameter keys. `action` is supplied by the batch entry point,
# so an element that carries its own action does not describe a rollback item.
ROLLBACK_ITEM_KEYS = frozenset({"environment", "budget", "changes", "applied", "retain"})

# G3: the ordered request list is 1..MAX_BATCH_ITEMS long.
