        raise JournalError("invalid-batch")
    if request.get("action") != "rollback-many":
        raise JournalError("invalid-batch")
    items = request.get("requests")
    if not isinstance(items, list) or not 1 <= len(items) <= MAX_BATCH_ITEMS:
        raise JournalError("invalid-batch")
    return items


def read_batch_item(item):
    """Turn one batch element into a single rollback request.

    The item is a rollback parameter object without `action`; the batch entry
    point fixes the action. Environment, budget, changes, applied and retain are
    validated by the single-request path, so G2 rules apply unchanged per item.
    """
    if not isinstance(item, dict):
        raise JournalError("invalid-batch-item")
    if set(item) - ROLLBACK_ITEM_KEYS:
        raise JournalError("invalid-batch-item")
    rollback = dict(item)
    rollback["action"] = "rollback"
    return rollback

