def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    # G3 adds one action to the existing envelope; when it is present the batch
    # entry point (G4) owns validation and result shape.
    if request.get("action") == "rollback-many":
        return rollback_many(request)
    try:
        actions, units = compute(request)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}


def rollback_many(request):
    """G4 batch rollback: ordered, de-duplicated by operation ID, all-or-nothing.

    Processing order is fixed by the spec and matters because the first actual
    failure wins:

      1. the batch envelope and its `limit` (before any item);
      2. every item's own shape and operation ID, in request order;
      3. duplicate/conflict decisions, in request order;
      4. G2 validation and computation, only for a first-seen operation ID that
         passed step 3 (a retry is never recomputed or billed again);
      5. only if the whole batch got this far, the batch limit over the
         de-duplicated units.

    A repeated operation ID whose complete rollback parameters are equivalent is
    a retry: it contributes no result of its own, the earlier one is returned,
    and it costs nothing. The same ID with different parameters is a conflict at
    the position of the later item. The batch limit never applies to a single
    rollback, which G2 leaves uncapped.
    """
    try:
        items, limit = read_batch(request)
    except JournalError as exc:
        return batch_failure(str(exc), None)

    # Step 2: shape and identity of every item, still in request order.
    prepared = []
    for index, item in enumerate(items):
        try:
            prepared.append(read_batch_item(item))
        except JournalError as exc:
            return batch_failure(str(exc), index)

    # Steps 3 and 4 share one request-order pass. Each operation ID records the
    # canonical rollback request its first item produced, so a later equivalent
    # item is a retry and a later different one is a conflict.
    results = []
    seen = {}
    for index, (rollback, operation_id) in enumerate(prepared):
        signature = _signature(rollback.get("changes"), rollback.get("applied", []),
                               rollback.get("retain", []))
        previous = seen.get(operation_id)
        if previous is not None:
            if previous != signature:
                return batch_failure("conflicting-operation", index)
            continue
        seen[operation_id] = signature
        try:
            actions, units = compute(rollback)
        except (PolicyError, JournalError) as exc:
            return batch_failure(str(exc), index)
        results.append({"operationId": operation_id, "actions": actions, "units": units})

    # The limit covers one of each distinct operation: retries were never added.
    units = sum(result["units"] for result in results)
    if units > limit:
        return batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": units}


def _signature(changes, applied, retain):
    """Canonical, hashable form of one rollback request's data.

    Equality of rollback requests ignores object key order and array order, but
    keeps the lexical structure of every scalar. Scalars are tagged by JSON
    type, so the number 1 and the boolean true never compare equal. Anything
    this cannot normalize is left distinct by identity, which can only turn a
    retry into an error, never the other way round.
    """
    return (_normalize(changes), _normalize(applied), _normalize(retain))


def _normalize(value):
    if isinstance(value, dict):
        return frozenset((key, _normalize(item)) for key, item in value.items())
    if isinstance(value, list):
        # A multiset, not a sequence: G4 retries must survive any array order.
        return frozenset(_normalize(item) for item in value)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    if value is None:
        return ("null",)
    return ("other", type(value).__name__, repr(value))

