journal.py.text:
"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _id_list(entries, error):
    """Validate a JSON array of nonempty change IDs.

    `depends_on`, `applied` and `retain` share this shape. A bare string, an
    object, a number or a null is a malformed field, not an empty one; and the
    empty string does not name a change, so it is malformed too.
    """
    if not isinstance(entries, list):
        raise JournalError(error)
    for entry in entries:
        if not isinstance(entry, str) or not entry:
            raise JournalError(error)
    return entries


def _read_dependencies(row):
    return _id_list(row.get("depends_on", []), "invalid-change")


def read_changes(records):
    """Validate records, collapse identical duplicates and reject conflicting IDs.

    Deduplication must happen *before* graph construction and before any units
    are summed (SPEC.md line 11): if a repeated record survived, plan would
    charge its units twice and rollback could emit the same ID twice, and if a
    later record simply overwrote an earlier one, a conflicting ID would pass
    silently. `depends_on` is compared as a set because equality of records
    covers the set of dependencies, not the list order or repetition.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    unique = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": frozenset(_read_dependencies(row)),
        }
        previous = unique.get(change["id"])
        if previous is None:
            unique[change["id"]] = change
        elif previous != change:
            raise JournalError("conflicting-change")
    return [unique[key] for key in sorted(unique)]


def read_applied(journal):
    """Validate the persisted release journal and return its unique change IDs."""
    return set(_id_list(journal, "invalid-change"))


def read_retain(request, applied):
    """Read the G2 rollback `retain` list: applied IDs that must remain installed.

    `retain` defaults to empty. Malformed lists are rejected here; an ID that is
    a valid string but was never applied is rejected here too, because that needs
    the persisted journal and no other module is allowed to own it. Repeated IDs
    are harmless; the value is consumed as a set.

    The check is deliberately against `applied` and not against the graph:
    `invalid-retain` answers "you asked to keep something that is not installed",
    while an applied-but-unknown ID is already `unknown-dependency` upstream.
    """
    retained = set(_id_list(request.get("retain", []), "invalid-retain"))
    if not retained <= applied:
        raise JournalError("invalid-retain")
    return retained

planner.py.text:
"""Compose policy and journal data into a plan.

Owns graph construction, deterministic ordering and result assembly. Two public
entry shapes: a single request (`plan` or `rollback`, G1/G2) and the G3
`rollback-many` batch. Batch items reuse the same single-request machinery so
per-item semantics can never drift from the G2 behaviour.
"""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, limit_for

BATCH_ACTION = "rollback-many"
BATCH_FIELDS = frozenset({"action", "requests"})
# A batch item is a single rollback request minus `action` (the entrypoint sets
# it to rollback), so these are the only keys an item may carry.
ITEM_FIELDS = frozenset({"environment", "budget", "changes", "applied", "retain"})
ITEM_REQUIRED = ("environment", "budget", "changes")
BATCH_MIN_ITEMS = 1
BATCH_MAX_ITEMS = 128


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _batch_failure(code, index):
    """Batch error shape: null index for the top level, real index for an item.

    The index is the position of the failing item, not `len(results)`: the two
    agree today only because items are processed in order and the first failure
    ends the batch. Deriving it from results would silently point at the next
    item if that ever changes.
    """
    return {"status": "error", "error": code, "requestIndex": index,
            "results": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    Sorting the *eligible frontier* (not the input) is what makes the order a
    function of the graph alone, which rollback depends on: reversing it for the
    same graph must always yield the same reverse order.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. An unapplied dependency is not installed and so is never kept, but the
    walk continues through it: c -> b(unapplied) -> a still keeps a when c is
    retained, because a is installed and c still needs it.

    That is why every dependency is pushed whether or not it is applied, and
    only applied ones are added to `keep`. `seen` is the walk fence and must stay
    separate from `keep`: using `keep` alone would re-push unapplied nodes
    forever (or stop at them), which is exactly the bug this replaced. Treating
    an unapplied node as a leaf silently drops a's retention and rolls back a
    still-needed dependency (SPEC.md line 28). The walk is iterative with an
    explicit stack so a 2000-long chain cannot exhaust the recursion limit.
    """
    keep = set(retained)
    seen = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in seen:
                continue
            seen.add(target)
            if target in applied:
                keep.add(target)
            stack.append(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def single_result(request):
    """Compute the result for one plan/rollback request.

    Returns a normal result, or an error object carrying `actions`/`units` for
    the single-request shape. Raises PolicyError/JournalError rather than
    converting them, so the batch can attach the right request index while the
    single entry keeps its historical error shape.

    Evaluation order is part of the contract: policy first (so a frozen
    production request is reported before any graph or change validation runs),
    then changes, applied, graph, cycle and finally retain.
    """
    policy = limit_for(request)
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied", []))
    by_id = build_graph(changes)
    if not applied <= by_id.keys():
        # The persisted journal names a change this request does not describe.
        # Same code as a dangling dependency: the graph and the journal cannot
        # be reconciled, so the request cannot be reasoned about at all.
        raise JournalError("unknown-dependency")
    order = topological_order(by_id)
    if policy.action == "rollback":
        # `retain` is meaningful for rollback only; a plan ignores the field
        # (including a malformed one) exactly as it did before G2.
        retained = read_retain(request, applied)
        actions = rollback_actions(by_id, order, applied, retained)
    else:
        # Only unapplied changes are emitted, and only they count against the
        # budget: applied entries satisfy dependencies but cost nothing new.
        actions = [key for key in order if key not in applied]
        if sum(by_id[key]["units"] for key in actions) > policy.limit:
            return failure("budget-exceeded")
    units = sum(by_id[key]["units"] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}


def _valid_batch(request):
    """Top-level structural check for rollback-many; no per-item inspection."""
    if not isinstance(request, dict):
        return False
    if set(request) != BATCH_FIELDS:
        # Strict: a top-level `changes`/`budget` in a batch is a caller mistake
        # worth reporting, not something to silently ignore.
        return False
    requests = request["requests"]
    return (isinstance(requests, list)
            and BATCH_MIN_ITEMS <= len(requests) <= BATCH_MAX_ITEMS)


def _valid_item(item):
    """Per-item structural check only; value errors stay with policy/journal.

    A missing required key or an `action` key is `invalid-batch-item`. A present
    but wrong-typed `budget` is not: it is a value error and must surface as the
    item's real `invalid-budget`.
    """
    return (isinstance(item, dict)
            and set(item) <= ITEM_FIELDS
            and all(key in item for key in ITEM_REQUIRED))


def _single_rollback(item):
    """Run one batch item as a rollback request and return {actions, units}.

    `action` is omitted from the item, so it is set here. Item isolation is the
    point: `changes`, `applied` and `retain` are read from this item alone --
    nothing is shared or carried between items.
    """
    request = dict(item)
    request["action"] = "rollback"
    result = single_result(request)
    return {"actions": result["actions"], "units": result["units"]}


def rollback_many(request):
    """G3 batch rollback: process items in order, fail the whole batch at the first error."""
    if not _valid_batch(request):
        return _batch_failure("invalid-batch", None)
    results = []
    total = 0
    for index, item in enumerate(request["requests"]):
        if not _valid_item(item):
            return _batch_failure("invalid-batch-item", index)
        try:
            result = _single_rollback(item)
        except (PolicyError, JournalError) as exc:
            # First failing item wins, with its own real code and index. Anything
            # collected so far is discarded: the batch never reports partial
            # results, and the top-level units must not count them.
            return _batch_failure(str(exc), index)
        results.append(result)
        total += result["units"]
    return {"status": "ok", "results": results, "units": total}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    if request.get("action") == BATCH_ACTION:
        return rollback_many(request)
    try:
        return single_result(request)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

"""Compose policy and journal data into a plan."""
import heapq

from journal import (BATCH_ACTION, JournalError, is_valid_item, item_request,
                     read_applied, read_batch_head, read_changes, read_retain)
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def batch_failure(code, index=None):
    """Whole-batch failure. Emitted only once the batch is known to be rejected."""

    return {"status": "error", "error": code, "requestIndex": index,
            "results": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    Two questions must stay separate:

    1. Which changes are *kept*?  Only applied dependencies, because an
       unapplied change is not installed and so can never be retained. This is
       the sole purpose of `applied` here.
    2. How far does the *walk* go?  Across the whole graph, always. An unapplied
       node contributes nothing to the keep set, but the changes it depends on
       are still reachable ancestors: c -> b(unapplied) -> a must keep a, since
       a is applied and c still needs it. SPEC.md G3 states a batch must
       "trace the full dependency graph, then exclude only applied ancestors".

    `applied` is used only to decide what is kept. It must not be used to decide
    where the walk stops: the earlier version folded both questions into one
    branch and cut the walk at unapplied nodes, which both retained too little
    and wrongly reverted reachable applied ancestors.

    `expanded` marks nodes already pushed, so each node is expanded at most once
    and a 2,000 change graph stays linear rather than recursing or rescanning.
    """
    keep = set(retained)
    expanded = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in applied:
                keep.add(target)
            # Push regardless of whether the target is applied: an unapplied
            # node is a pass-through to its own ancestors, not a cut.
            if target not in expanded:
                expanded.add(target)
                stack.append(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def rollback_result(request):
    """Execute one rollback request and return a (error code or None, result) pair.

    `request` must already carry `action: "rollback"`. Both the standalone
    rollback path and every batch element go through this function, so a batch
    item can never diverge from a single rollback in ordering or replay
    handling. Nothing is cached or shared between calls: each call rebuilds its
    graph from its own `changes`/`applied`/`retain`, which is what keeps batch
    items independent of one another.

    Both the standalone rollback and every batch item traverse the full graph
    and filter only the keep set, so the two cannot diverge.

    The success value is the single-item shape `{"status","actions","units"}`.
    """
    try:
        # Policy runs before any graph work so a frozen production item reports
        # production-frozen even when its own graph is malformed.
        policy = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        by_id = build_graph(changes)
        if not applied <= by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        retained = read_retain(request, applied)
        # The budget was validated by limit_for but intentionally never compared
        # here: G2 forbids capping a rollback, since a cap would leave the
        # environment half-reverted.
        actions = rollback_actions(by_id, order, applied, retained)
    except (PolicyError, JournalError) as exc:
        return str(exc), None
    units = sum(by_id[key]["units"] for key in actions)
    return None, {"status": "ok", "actions": actions, "units": units}


def plan_batch(request):
    """Run every element as an independent rollback and assemble one response.

    Error precedence, and why it is this way: only the top-level shape is
    checked up front (`invalid-batch` with a null index). Element shapes are
    checked when the stream reaches that element, interleaved with execution,
    so a business failure in an earlier element is reported before a later
    element's shape problem. That is the "first failing item's real error code
    ends the batch" rule applied to every kind of failure, and it is what the
    approved example pins down (element 0 production-frozen wins over element 1
    malformed). Before executing an element its shape is still checked first,
    so `invalid-batch-item` always carries that element's own index.

    `results` keeps request order and the top-level `units` is the sum of the
    per-item units, so a caller can reconcile the batch without re-reading it.
    """
    try:
        items = read_batch_head(request)
    except JournalError as exc:
        return batch_failure(str(exc))
    results = []
    total = 0
    for index, row in enumerate(items):
        if not is_valid_item(row):
            return batch_failure("invalid-batch-item", index)
        item = item_request(row)
        # Batch items and single rollbacks share one traversal; see retained_closure.
        code, result = rollback_result(item)
        if code is not None:
            # First failing element ends the batch; later items are never
            # executed and their outcomes are never reported.
            return batch_failure(code, index)
        results.append({"actions": result["actions"], "units": result["units"]})
        total += result["units"]
    return {"status": "ok", "results": results, "units": total}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    if request.get("action") == BATCH_ACTION:
        # The batch keeps its own result shape (`results`/`requestIndex`), so it
        # must never fall through to the single-item paths below, which always
        # answer with exactly one of the G1/G2 shapes.
        return plan_batch(request)
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        by_id = build_graph(changes)
        if not applied <= by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        if policy.action == "rollback":
            # Reuse the batch element path so single rollback and batch items
            # share ordering, replay and retain semantics by construction. It
            # reports failures as (code, None) instead of raising, so the code
            # must be translated back here rather than falling through to the
            # `actions` below, which would be undefined.
            code, result = rollback_result(request)
            return failure(code) if code is not None else result
        actions = [key for key in order if key not in applied]
        if sum(by_id[key]["units"] for key in actions) > policy.limit:
            return failure("budget-exceeded")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = sum(by_id[key]["units"] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}

