"""JSON transport for the release planner."""
import json
import sys

from planner import plan


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        # A `rollback-many` batch is dispatched by planner.plan, which answers with
        # the batch shape (`results`/`requestIndex`). Transport stays shape-blind:
        # it must not add or strip keys, because that would rewrite a
        # requestIndex the planner already decided.
        result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

