"""JSON transport for the release planner."""
import json
import sys

from planner import failure, plan, rollback_many

# G3: the only two top-level fields a rollback-many request may carry. The
# nested requests describe themselves; anything else here would be an extension
# the planner cannot honour, so it is rejected instead of silently ignored.
BATCH_FIELDS = frozenset({"action", "requests"})

# Sized for independent operations, not for bulk load; a larger batch is more
# likely a runaway caller than a legitimate rollback.
MAX_BATCH = 128


def dispatch(request):
    """Route a decoded request to the planner. Transport only: no business rules."""
    if not isinstance(request, dict):
        return failure("invalid-request")
    # Only the batch action is recognized here. A missing, non-string or unknown
    # action falls through to plan(), which keeps G1's invalid-request /
    # unsupported-action answers exactly as they were, and a batch must never be
    # inferred from the presence of "requests".
    if request.get("action") == "rollback-many":
        if not set(request) <= BATCH_FIELDS:
            return _batch_error("invalid-batch")
        requests = request.get("requests")
        if not isinstance(requests, list) or not 1 <= len(requests) <= MAX_BATCH:
            return _batch_error("invalid-batch")
        return rollback_many(request)
    return plan(request)


def _batch_error(code):
    # Top-level batch problems have no element to point at, hence a null index.
    return {"status": "error", "error": code, "requestIndex": None, "results": [], "units": 0}


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = failure("invalid-json")
    else:
        result = dispatch(request)
    # One response, then normal exit: errors are data, not crashes.
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

