"""Compose policy and journal data into a plan."""
import heapq

from journal import (
    JournalError,
    read_applied,
    read_batch_items,
    read_changes,
    read_retain,
)
from policy import (
    BATCH_ACTION,
    ENVIRONMENTS,
    FROZEN_ENVIRONMENTS,
    PolicyError,
    check_budget,
    limit_for,
)


# G3: the batch size bounds a rollback-many request. Enforced by the transport
# shape check in release.py; kept here as the documented contract value.
MAX_BATCH = 128


def batch_failure(code, index=None):
    """G3 error shape: always all four fields, `requestIndex` null for a bad batch."""
    return {
        "status": "error",
        "error": code,
        "requestIndex": index,
        "results": [],
        "units": 0,
    }


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. The walk runs over the *complete* graph and only applied ancestors are
    added to the keep set: c -> b(unapplied) -> a still keeps a when c is
    retained, because a is installed and c still needs it. An unapplied
    dependency is walked through but never kept -- it is not installed, so there
    is nothing to leave behind.
    """
    keep = set(retained)
    seen = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target not in seen:
                seen.add(target)
                stack.append(target)
            if target in applied:
                keep.add(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def solve_rollback(request, decision):
    """Return the applied IDs a single rollback emits, in the G2 order.

    Shared verbatim by the single rollback path and by every rollback-many
    element, so the two cannot diverge on ordering, retention or the graph walk.
    Budget is not consulted: G2 lets a rollback ignore the plan quota, capping it
    would leave the environment half-reverted.
    """
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied", []))
    by_id = build_graph(changes)
    if not applied <= by_id.keys():
        raise JournalError("unknown-dependency")
    order = topological_order(by_id)
    retained = read_retain(request, applied)
    return by_id, rollback_actions(by_id, order, applied, retained)


def rollback_many(request):
    """G3: run every element of a rollback-many batch or report the first failure.

    The transport has already proven the top-level shape (only `action` and
    `requests`, 1..128 elements, otherwise invalid-batch). Elements are then
    visited strictly in request order and each one is judged in full before the
    next is looked at: an element whose shape is bad reports invalid-batch-item
    at its own index, but only when it is that element's turn. Batching the shape
    pre-check ahead of the loop would let a later malformed element mask an
    earlier element's domain error (production-frozen, invalid-budget, ...),
    which G3 forbids -- the *first* failing element wins.

    Elements are independent: no IDs, `applied` journals or `retain` sets are
    carried across iterations. The whole batch fails on the first offending
    element with that element's real error code, so no partial results are
    emitted -- a caller either reverts everything it asked for or nothing.
    """
    requests = request["requests"]
    results = []
    total = 0
    for index, item in enumerate(requests):
        try:
            # Structure first, so a malformed element never reaches a field read
            # in the business path below.
            if read_batch_items([item]) is not None:
                raise JournalError("invalid-batch-item")
            # The batch entry point owns the action, so an element can only ever
            # be a rollback; environment/budget keep their usual owners and the
            # production freeze still fires before any graph validation.
            environment = item.get("environment")
            if not isinstance(environment, str) or environment not in ENVIRONMENTS:
                raise PolicyError("invalid-environment")
            if environment in FROZEN_ENVIRONMENTS:
                raise PolicyError("production-frozen")
            check_budget(item.get("budget"))
            decision = limit_for(dict(item, action=BATCH_ACTION))
            by_id, actions = solve_rollback(item, decision)
        except (PolicyError, JournalError) as exc:
            return batch_failure(str(exc), index)
        units = sum(by_id[key]["units"] for key in actions)
        results.append({"actions": actions, "units": units})
        total += units
    return {"status": "ok", "results": results, "units": total}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        by_id = build_graph(changes)
        if not applied <= by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        if policy.action == "rollback":
            retained = read_retain(request, applied)
            actions = rollback_actions(by_id, order, applied, retained)
        else:
            actions = [key for key in order if key not in applied]
            if sum(by_id[key]["units"] for key in actions) > policy.limit:
                return failure("budget-exceeded")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = sum(by_id[key]["units"] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}

