"""JSON transport for the release planner."""
import json
import sys

from planner import MAX_BATCH, batch_failure, plan, rollback_many
from journal import JournalError
from policy import PolicyError


# G3: the only top-level fields a rollback-many request may carry.
BATCH_FIELDS = frozenset({"action", "requests"})


def error(code, extra=None):
    result = {"status": "error", "error": code, "actions": [], "units": 0}
    if extra:
        result.update(extra)
    return result


def dispatch(request):
    """Route one parsed request; transport decides batch *shape* only.

    A request is a batch solely when its action is rollback-many. Everything
    else goes down the untouched single-request path. A broken batch shape is
    reported as invalid-batch with a null requestIndex, before any element is
    looked at, so a caller never receives a positional error for a request whose
    top level was never valid.
    """
    if not isinstance(request, dict):
        return error("invalid-request")
    if request.get("action") != "rollback-many":
        return plan(request)
    requests = request.get("requests")
    if (not request.keys() <= BATCH_FIELDS or not isinstance(requests, list)
            or not 1 <= len(requests) <= MAX_BATCH):
        return batch_failure("invalid-batch")
    return rollback_many(request)


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = error("invalid-json")
    else:
        try:
            result = dispatch(request)
        except (PolicyError, JournalError) as exc:
            # Last line of defence: every request must still answer with exactly
            # one JSON object and exit 0, so a domain error that escaped a handler
            # is still reported by its code instead of a traceback. The batch
            # path catches its own errors per element to attach requestIndex;
            # reaching here only happens for the single-request path.
            result = error(str(exc))
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

