"""Compose policy and journal data into a plan."""
import heapq

from journal import (
    JournalError,
    read_applied,
    read_batch_items,
    read_changes,
    read_operation_id,
    read_retain,
)
from policy import (
    BATCH_ACTION,
    ENVIRONMENTS,
    FROZEN_ENVIRONMENTS,
    PolicyError,
    batch_limit,
    check_budget,
    limit_for,
)


# G3: the batch size bounds a rollback-many request. Enforced by the transport
# shape check in release.py; kept here as the documented contract value.
MAX_BATCH = 128

# G4: fields whose values are order-sensitive containers. Two elements with the
# same operation_id are a retry only when every value matches *exactly*; the
# comparison below deliberately does not reuse Python equality, which would
# call 1 and 1.0 or True and 1 the same.
_MAX_IDENTITY_DEPTH = 32


def batch_failure(code, index=None):
    """G3/G4 error shape: all five fields, `requestIndex` null when no element is to blame."""
    return {
        "status": "error",
        "error": code,
        "requestIndex": index,
        "results": [],
        "units": 0,
    }


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. The walk runs over the *complete* graph and only applied ancestors are
    added to the keep set: c -> b(unapplied) -> a still keeps a when c is
    retained, because a is installed and c still needs it. An unapplied
    dependency is walked through but never kept -- it is not installed, so there
    is nothing to leave behind.
    """
    keep = set(retained)
    seen = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target not in seen:
                seen.add(target)
                stack.append(target)
            if target in applied:
                keep.add(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def solve_rollback(request, decision):
    """Return the applied IDs a single rollback emits, in the G2 order.

    Shared verbatim by the single rollback path and by every rollback-many
    element, so the two cannot diverge on ordering, retention or the graph walk.
    Budget is not consulted: G2 lets a rollback ignore the plan quota, capping it
    would leave the environment half-reverted.
    """
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied", []))
    by_id = build_graph(changes)
    if not applied <= by_id.keys():
        raise JournalError("unknown-dependency")
    order = topological_order(by_id)
    retained = read_retain(request, applied)
    return by_id, rollback_actions(by_id, order, applied, retained)


def request_identity(value, depth=0):
    """G4: a comparable fingerprint of one batch element's request data.

    Two elements mean the same request only when their full data matches: object
    member *order* is irrelevant (a dict is hashed from its sorted members),
    array *order* matters (a list stays an ordered tuple), and the JSON scalar
    types must match exactly. Python's own `==` cannot express the last rule --
    True == 1 and 1 == 1.0 -- so every scalar is tagged with its type name
    instead of compared as a bare value. That is what makes an operation_id
    followed by `true` a conflict with the same id followed by `3` rather than a
    retry that silently reuses the wrong result.

    This never raises: it is called before element validation, and a malformed
    element must still be reported at its own index as invalid-batch-item by the
    normal path, not turned into a conflict.
    """
    if isinstance(value, dict):
        if depth >= _MAX_IDENTITY_DEPTH:
            return ("depth", depth)
        return ("object", tuple(
            (key, request_identity(member, depth + 1))
            for key, member in sorted(value.items())))
    if isinstance(value, list):
        if depth >= _MAX_IDENTITY_DEPTH:
            return ("depth", depth)
        return ("array", tuple(request_identity(row, depth + 1) for row in value))
    if value is None or isinstance(value, bool):
        return (type(value).__name__, value)
    if isinstance(value, (int, float, str)):
        return ("number" if isinstance(value, (int, float)) else "string", value)
    return (type(value).__name__, repr(value))


def _checked_operation_id(index, item):
    """G4 step 1 for one element: structure, then the required operation_id.

    Returns the ID, which by construction can only come from a well-shaped
    element. Raising here is safe because the caller attributes the error to
    `index`; an element that is not an object at all has no operation_id to
    read, so it fails with the same invalid-batch-item code.
    """
    if read_batch_items([item]) is not None:
        raise JournalError("invalid-batch-item")
    return read_operation_id(item)


def solve_batch_item(index, item):
    """G4: the G2 rollback work for one *new* operation_id.

    Everything here mirrors the single rollback path exactly, because a batch
    element is the same request minus its own `action`. Order matters: the
    environment and the production freeze are decided before any graph or change
    validation, so a frozen production element reports production-frozen even
    with a malformed graph, just like a single request. Budget is validated but
    never caps the element -- the batch `limit` is the only ceiling, and it is
    compared after the whole batch succeeded.
    """
    environment = item.get("environment")
    if not isinstance(environment, str) or environment not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    if environment in FROZEN_ENVIRONMENTS:
        raise PolicyError("production-frozen")
    check_budget(item.get("budget"))
    # The batch entry point owns the action, so an element can only ever be a
    # rollback; action=BATCH_ACTION makes that explicit rather than implied.
    decision = limit_for(dict(item, action=BATCH_ACTION))
    by_id, actions = solve_rollback(item, decision)
    return by_id, actions


def rollback_many(request):
    """G4: run every new operation of a rollback-many batch or fail the batch.

    The transport has already proven the top-level shape (only action, limit and
    requests; 1..128 elements, otherwise invalid-batch), so `limit` is read here
    only for validation and the later comparison.

    Elements are visited strictly in request order and each is judged in full
    before the next is looked at: shape and operation_id first, then retry or
    conflict, and only then the G2 business checks for a new ID. Batched
    pre-checks ahead of the loop would let a later malformed element mask an
    earlier element's real error, which the owner's ordering forbids -- the
    *first* failing element wins.

    Repeats are library semantics, not an optimisation: an element whose id was
    already seen with identical request data is a retry of work already accepted,
    so it contributes neither a second result nor a second charge. A same id with
    different data is ambiguous and fails with conflicting-operation at the later
    element, because the caller cannot be told which of two promises holds.

    The limit is compared only after every element succeeded: a real failure
    anywhere outranks the quota, and until then nothing is emitted at all. The
    whole batch fails on the first offending element with that element's real
    error code, so a caller either reverts everything it asked for or nothing.
    """
    requests = request["requests"]
    try:
        limit = batch_limit(request.get("limit"))
    except PolicyError:
        return batch_failure("invalid-batch")
    results = []
    total = 0
    seen = {}
    for index, item in enumerate(requests):
        try:
            operation_id = _checked_operation_id(index, item)
            identity = request_identity(item)
            previous = seen.get(operation_id)
            if previous is not None:
                if previous[0] != identity:
                    raise JournalError("conflicting-operation")
                # Retry: the first result already covers this request.
                continue
            by_id, actions = solve_batch_item(index, item)
        except (PolicyError, JournalError) as exc:
            return batch_failure(str(exc), index)
        units = sum(by_id[key]["units"] for key in actions)
        seen[operation_id] = (identity, len(results))
        results.append({"actions": actions, "units": units, "operationId": operation_id})
        total += units
    if total > limit:
        # Only reachable once every element computed, so this never hides a real
        # error; the quota belongs to the batch, hence no requestIndex.
        return batch_failure("batch-limit-exceeded")
    return {"status": "ok", "results": results, "units": total}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        by_id = build_graph(changes)
        if not applied <= by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        if policy.action == "rollback":
            retained = read_retain(request, applied)
            actions = rollback_actions(by_id, order, applied, retained)
        else:
            actions = [key for key in order if key not in applied]
            if sum(by_id[key]["units"] for key in actions) > policy.limit:
                return failure("budget-exceeded")
